export type IWuKongClient = {
	-- 获取悟空门面,必须在 Start 之后调用
	-- @return IWuKongFacade 返回悟空门面实例
	GetFacade: (self: IWuKongClient) -> IWuKongFacade,

	-- 启动悟空客户端
	-- @param options WuKongOptions 悟空客户端配置
	-- @return IWuKongRbxFacade 返回悟空门面实例
	Start: (self: IWuKongClient, options: IWuKongOptions) -> IWuKongFacade,

	-- 注销
	Dispose: (self: IWuKongClient) -> (),
}
